INSERT INTO service_types (name, description, base_price, unit, is_active, category, location, open_hours, contact_phone) VALUES
('BlueFit Gym & Yoga Center', 'Trung tâm thể hình đẳng cấp 5 sao với máy móc Technogym nhập khẩu Ý. Có bể bơi 4 mùa, xông hơi và các lớp Yoga miễn phí.', 500000, 'Tháng', TRUE, 'Sức khỏe & Làm đẹp', 'Tầng 3 - Tòa A', '05:30 - 22:00', '0901.234.567'),
('Siêu thị BlueMart (Đi chợ hộ)', 'Dịch vụ đi chợ hộ dành cho cư dân bận rộn. Phí dịch vụ tính trên một lần đi mua.', 30000, 'Lần', TRUE, 'Tiện ích đời sống', 'Tầng 1 - Tòa B', '07:00 - 21:00', '0909.888.999'),
('Moonlight Coffee & Lounge', 'Thuê phòng VIP để họp nhóm, tiếp khách hoặc làm việc. Không gian yên tĩnh, view toàn thành phố.', 200000, 'Giờ', TRUE, 'Ẩm thực & Giải trí', 'Tầng Thượng (Rooftop)', '08:00 - 23:00', '0912.333.444'),
('Trường Mầm non Little Stars', 'Môi trường giáo dục chuẩn quốc tế, giáo viên bản ngữ. Đăng ký giữ chỗ hoặc tham quan.', 8500000, 'Tháng', TRUE, 'Giáo dục', 'Tầng 2 - Tòa C', '07:00 - 17:30', '024.3333.8888'),
('Nhà hàng Ẩm thực Á Đông', 'Đặt bàn tiệc gia đình, sinh nhật, tất niên. Thực đơn phong phú 3 miền.', 3500000, 'Bàn', TRUE, 'Ẩm thực & Giải trí', 'Tầng 1 - Tòa D', '10:00 - 22:00', '0988.777.666'),
('Khu vui chơi KidzWorld', 'Thiên đường vui chơi cho trẻ em với nhà bóng, cầu trượt, khu hướng nghiệp.', 120000, 'Vé', TRUE, 'Giải trí', 'Tầng 2 - TTTM', '09:00 - 21:30', '0905.111.222');
INSERT INTO building_info (id, name, investor, location, scale, apartments, description, total_area, start_date, finish_date, total_investment) VALUES
(1, 'CHUNG CƯ BLUEMOON', 'Tổng công ty CP Xuất nhập khẩu & Xây dựng Việt Nam (VINACONEX)', '289 Khuất Duy Tiến - Trung Hòa - Cầu Giấy - Hà Nội', 'Cao 31 tầng, 03 tầng hầm, 04 tầng dịch vụ thương mại.', '496 căn hộ diện tích từ 85.5 - 120m²', 'Tọa lạc tại vị trí đắc địa, Chung cư Bluemoon tiếp giáp với nút giao thông trung tâm Vành đai 3 - Đại lộ Thăng Long - Trần Duy Hưng. Tòa nhà được thiết kế với không gian sống xanh, hòa với thiên nhiên cùng hệ thống hạ tầng khớp nối đồng bộ.', '1,3 ha', 'Quý IV/2016', 'Quý IV/2018', '618,737 tỷ đồng');
INSERT INTO building_regulations (title, content, sort_order) VALUES
('1. Quy định về An ninh & Ra vào', '["Cư dân ra vào tòa nhà phải sử dụng Thẻ Cư Dân.", "Khách đến thăm phải đăng ký tại Quầy Lễ Tân.", "Không cho người lạ vào thang máy hoặc khu vực hạn chế.", "Mọi hành vi gây mất trật tự sẽ bị xử lý."]', 1),
('2. Quy định về Tiếng ồn & Giờ giấc', '["Giờ yên tĩnh: 22:00 - 07:00 và 12:00 - 13:30.", "Thi công sửa chữa chỉ trong giờ hành chính (8:00 - 17:00).", "Không gây tiếng ồn ảnh hưởng căn hộ lân cận."]', 2),
('3. Quy định về Vệ sinh & Rác thải', '["Rác phải phân loại và bỏ vào túi kín.", "Không để rác tại hành lang chung.", "Cấm vứt rác từ ban công.", "Rác cồng kềnh phải đăng ký với BQL."]', 3),
('4. Quy định về PCCC', '["Cấm hút thuốc tại khu vực chung.", "Không đốt vàng mã tại ban công.", "Không chặn cửa thoát hiểm.", "Tham gia diễn tập PCCC định kỳ."]', 4),
('5. Quy định về Thú cưng', '["Phải đăng ký thú cưng với BQL.", "Ra ngoài phải có dây xích, rọ mõm.", "Chủ nuôi phải dọn chất thải ngay.", "Không để thú cưng gây ồn ào."]', 5);
