INSERT INTO notifications (id, title, content, type_id, target, scheduled_at, is_sent, created_by, created_at) VALUES
('TB-29092025-0001', 'Khẩn cấp: Sự cố thang máy', 'Thang máy tòa B tạm ngưng hoạt động để khắc phục sự cố. Dự kiến hoàn thành trong 2-3 giờ.', 1, 'Tất cả Cư dân', '2025-09-28 21:48:47', 1, 'ID0001', '2025-07-27 21:10:47'),
('TB-30122025-0001', 'Phun thuốc diệt muỗi', 'Tòa nhà sẽ tiến hành phun thuốc diệt muỗi vào sáng thứ 7 tuần này. Vui lòng đóng cửa sổ.', 2, 'Tất cả Cư dân', '2025-12-30 13:08:24', 0, 'ID0001', '2025-12-06 01:16:14'),
('TB-25122025-0001', 'Nhắc nhở đóng phí tháng 12', 'Kính gửi Quý cư dân, hạn đóng phí quản lý tháng 12 là ngày 10. Vui lòng thanh toán đúng hạn để tránh phát sinh lãi suất.', 3, 'Tất cả Cư dân', '2025-12-25 09:59:25', 1, 'ID0001', '2025-11-29 07:12:58'),
('TB-02012026-0001', 'Khẩn cấp: Sự cố thang máy', 'Thang máy tòa B tạm ngưng hoạt động để khắc phục sự cố. Dự kiến hoàn thành trong 2-3 giờ.', 1, 'Tất cả Cư dân', '2026-01-02 02:19:02', 0, 'ID0001', '2025-11-26 03:01:28'),
